@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .badge {
    --badge-fill: var(--ui-fill-strong);
    --badge-text: var(--ui-muted);
    --badge-dot: var(--ui-subtle);
    --badge-edge: var(--ui-border);
    /* A little taller than the line it sits on, so the pill has air above and
       below its letters and still sits inside a 24px row. */
    --badge-height: 24px;
    /* Half the height: the label starts where the round end stops. */
    --badge-pad: var(--ui-pad-tag);

    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    gap: 6px;
    box-sizing: border-box;
    height: var(--badge-height);
    max-width: 100%;
    padding-inline: var(--badge-pad);
    /* Not `middle`: that centers on the x-height and makes the line taller. */
    vertical-align: top;
    border-radius: var(--ui-radius-full);
    background: var(--badge-fill);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--badge-edge);
    color: var(--badge-text);
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    white-space: nowrap;
  }

  /* In running text (a badge straight inside a paragraph or list item) the
     pill is shorter than the line and its label sits on the sentence's
     baseline, so it reads as part of the line with room above and below and
     never touches the lines around it; a little room at the sides keeps
     punctuation off it. */
  :is(p, li, dd, figcaption) > .badge {
    --badge-height: 20px;
    --badge-pad: var(--ui-pad-tag-sm);
    margin-inline: 2px;
    vertical-align: baseline;
  }

  .badge[data-tone="accent"] {
    --badge-fill: var(--ui-accent-tint);
    --badge-edge: var(--ui-border-accent);
    --badge-text: var(--ui-accent-text);
    --badge-dot: var(--ui-accent);
  }

  .badge[data-tone="positive"] {
    --badge-fill: var(--ui-success-tint);
    --badge-edge: var(--ui-border-success);
    --badge-text: var(--ui-success-text);
    --badge-dot: var(--ui-success);
  }

  .badge[data-tone="danger"] {
    --badge-fill: var(--ui-danger-tint);
    --badge-edge: var(--ui-border-danger);
    --badge-text: var(--ui-danger-text);
    --badge-dot: var(--ui-danger);
  }

  .badge[data-tone="warning"] {
    --badge-fill: var(--ui-warning-tint);
    --badge-edge: var(--ui-border-warning);
    --badge-text: var(--ui-warning-text);
    --badge-dot: var(--ui-warning);
  }

  .badge[data-size="sm"] {
    --badge-height: 20px;
    --badge-pad: var(--ui-pad-tag-sm);
    gap: 5px;
  }

  .badge:has(.dot) {
    padding-inline-start: calc(var(--badge-pad) - 2px);
  }

  /* Trimmed to the capitals and the baseline, so centering the label centers
     the letters: the font's own spacing puts more room above them than below,
     which reads as text sitting high in a short pill. */
  .label {
    text-box: trim-both cap alphabetic;
  }

  .dot {
    flex-shrink: 0;
    width: 6px;
    height: 6px;
    border-radius: var(--ui-radius-full);
    background: var(--badge-dot);
  }

  .badge[data-count] {
    --badge-pad: var(--ui-pad-tag-sm);
    min-width: var(--badge-height);
    font-variant-numeric: tabular-nums;
  }

  .badge[data-count][data-size="sm"] {
    --badge-pad: calc(var(--ui-pad-tag-sm) - 2px);
  }

  /* Forced colors drop the tint and inset edge, so draw a real outline. */
  @media (forced-colors: active) {
    .badge {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }
    .dot {
      forced-color-adjust: none;
      background: CanvasText;
    }
  }
}

import type { ComponentProps, ReactNode } from "react";
import styles from "./badge.module.css";

// No "use client": stateless, so it renders on the server.

type Tone = "neutral" | "accent" | "positive" | "warning" | "danger";

type BadgeProps = Omit<ComponentProps<"span">, "children"> & {
  /** Status tone. `positive` and `danger` mean only done and failed. */
  tone?: Tone;
  /** A small mark in the tone's color before the label. */
  dot?: boolean;
  /** `md` fits a 15px line, `sm` a 13px one. */
  size?: "sm" | "md";
  /** The label, always in words. */
  children?: ReactNode;
  /** Show a number instead of a label. Over `max` it reads `99+`. */
  count?: number;
  max?: number;
  /** What the count means, for screen readers ("3 new replies"). */
  label?: string;
};

/** A small static label for a status or a count. */
export function Badge({
  tone = "neutral",
  dot = false,
  size = "md",
  count,
  max = 99,
  label,
  className,
  children,
  ...props
}: BadgeProps) {
  const isCount = count !== undefined;
  const shown = isCount ? (count > max ? `${max}+` : String(count)) : children;

  return (
    <span
      className={className ? `${styles.badge} ${className}` : styles.badge}
      data-tone={tone}
      data-size={size}
      data-count={isCount || undefined}
      {...props}
    >
      {dot && !isCount && <span className={styles.dot} aria-hidden="true" />}
      {isCount && label ? (
        <>
          <span className={styles.label} aria-hidden="true">
            {shown}
          </span>
          <span className={styles.srOnly}>{label}</span>
        </>
      ) : (
        <span className={styles.label}>{shown}</span>
      )}
    </span>
  );
}
